ts: o min: 1 o max: 8 (string) Constraints: o min: 1 o max: 255 o pattern: .* excludes -&gt; (list) The list of patterns of Git branches that, when a commit is pushed, are to be excluded from starting the pipeline. Constraints: o min: 1 o max: 8 (string) Constraints: o min: 1 o max: 255 o pattern: .* filePaths -&gt; (structure) The field that specifies to filter on file paths for the push trigger configuration. includes -&gt; (list) The list of patterns of Git repository file paths that, when a commit is pushed, are to be included as criteria that starts the pipeline. Constraints: o min: 1 o max: 8 (string) Constraints: o min: 1 o max: 255 o pattern: .* excludes -&gt; (list) The list of patterns of Git repository file paths that, when a commit is pushed, are to be excluded from starting the pipeline. Constraints: o min: 1 o max: 8 (string) Constraints: o min: 1 o max: 255 o pattern: .* pullRequest -&gt; (list) The field where the repository event that will start the pipeline is specified as pull requests. Constraints: o min: 1 o max: 3 (structure) The event criteria for the pull request trigger configuration, such as the lists of branches or file paths to include and exclude. The following are valid values for the events for this filter: o CLOSED o OPEN o UPDATED events -&gt; (list) The field that specifies which pull request events to filter on (OPEN, UPDATED, CLOSED) for the trigger configuration. Constraints: o min: 1 o max: 3 (string) Possible values: o OPEN o UPDATED o CLOSED branches -&gt; (structure) The field that specifies to filter on branches for the pull request trigger configuration. includes -&gt; (list) The list of patterns of Git branches that, when a commit is pushed, are to be included as criteria that starts the pipeline. Constraints: o min: 1 o max: 8 (string) Constraints: o min: 1 o max: 255 o pattern: .* excludes -&gt; (list) The list of patterns of Git branches that, when a commit is pushed, are to be excluded from starting the pipeline. Constraints: o min: 1 o max: 8 (string) Constraints: o min: 1 o max: 255 o pattern: .* filePaths -&gt; (structure) The field that specifies to filter on file paths for the pull request trigger configura- tion. includes -&gt; (list) The list of patterns of Git repository file paths that, when a commit is pushed, are to be included as criteria that starts the pipeline. Constraints: o min: 1 o max: 8 (string) Constraints: o min: 1 o max: 255 o pattern: .* excludes -&gt; (list) The list of patterns of Git repository file paths that, when a commit is pushed, are to be excluded from starting the pipeline. Constraints: o min: 1 o max: 8 (string) Constraints: o min: 1 o max: 255 o pattern: .* JSON Syntax: { "name": "string", "roleArn": "string", "artifactStore": { "type": "S3", "location": "string", "encryptionKey": { "id": "string", "type": "KMS" } }, "artifactStores": {"string": { "type": "S3", "location": "string", "encryptionKey": { "id": "string", "type": "KMS" } } ...}, "stages": [ { "name": "string", "blockers": [ { "name": "string", "type": "Schedule" } ... ], "actions": [ { "name": "string", "actionTypeId": { "category": "Source"|"Build"|"Deploy"|"Test"|"Invoke"|"Approval"|"Compute", "owner": "AWS"|"ThirdParty"|"Custom", "provider": "string", "version": "string" }, "runOrder": integer, "configuration": {"string": "string" ...}, "commands": ["string", ...], "outputArtifacts": [ { "name": "string", "files": ["string", ...] } ... ], "inputArtifacts": [ { "name": "string" } ... ], "outputVariables": ["string", ...], "roleArn": "string", "region": "string", "namespace": "string", "timeoutInMinutes": integer, "environmentVariables": [ { "name": "string", "value": "string", "type": "PLAINTEXT"|"SECRETS_MANAGER" } ... ] } ... ], "onFailure": { "result": "ROLLBACK"|"FAIL"|"RETRY"|"SKIP", "retryConfiguration": { "retryMode": "FAILED_ACTIONS"|"ALL_ACTIONS" }, "conditions": [ { "result": "ROLLBACK"|"FAIL"|"RETRY"|"SKIP", "rules": [ { "name": "string", "ruleTypeId": { "category": "Rule", "owner": "AWS", "provider": "string", "version": "string" }, "configuration": {"string": "string" ...}, "commands": ["string", ...], "inputArtifacts": [ { "name": "string" } ... ], "roleArn": "string", "region": "string", "timeoutInMinutes": integer } ... ] } ... ] }, "onSuccess": { "conditions": [ { "result": "ROLLBACK"|"FAIL"|"RETRY"|"SKIP", "rules": [ { "name": "string", "ruleTypeId": { "category": "Rule", "owner": "AWS", "provider": "string", "version": "string" }, "configuration": {"string": "string" ...}, "commands": ["string", ...], "inputArtifacts": [ { "name": "string" } ... ], "roleArn": "string", "region": "string", "timeoutInMinutes": integer } ... ] } ... ] }, "beforeEntry": { "conditions": [ { "result": "ROLLBACK"|"FAIL"|"RETRY"|"SKIP", "rules": [ { "name": "string", "ruleTypeId": { "category": "Rule", "owner": "AWS", "provider": "string", "version": "string" }, "configuration": {"string": "string" ...}, "commands": ["string", ...], "inputArtifacts": [ { "name": "string" } ... ], "roleArn": "string", "region": "string", "timeoutInMinutes": integer } ... ] } ... ] } } ... ], "version": integer, "executionMode": "QUEUED"|"SUPERSEDED"|"PARALLEL", "pipelineType": "V1"|"V2", "variables": [ { "name": "string", "defaultValue": "string", "description": "string" } ... ], "triggers": [ { "providerType": "CodeStarSourceConnection", "gitConfiguration": { "sourceActionName": "string", "push": [ { "tags": { "includes": ["string", ...], "excludes": ["string", ...] }, "branches": { "includes": ["string", ...], "excludes": ["string", ...] }, "filePaths": { "includes": ["string", ...], "excludes": ["string", ...] } } ... ], "pullRequest": [ { "events": ["OPEN"|"UPDATED"|"CLOSED", ...], "branches": { "includes": ["string", ...], "excludes": ["string", ...] }, "filePaths": { "includes": ["string", ...], "excludes": ["string", ...] } } ... ] } } ... ] }</param>
